## Code Example
```javascript
// Playwright E2E test
import { test, expect } from '@playwright/test';

test.describe('Notifications Center feature flag', () => {
  const enabledUser = { id: 'user-1', email: 'enabled@example.com', flags: { notificationsCenter: true } };
  const disabledUser = { id: 'user-2', email: 'disabled@example.com', flags: { notificationsCenter: false } };

  test('enabled user sees Notifications Center and receives sample notification', async ({ page }) => {
    await seedUser(enabledUser);
    await page.goto('/login');
    await page.fill('[name=email]', enabledUser.email);
    await page.fill('[name=password]', 'password123');
    await page.click('[type=submit]');

    await expect(page.locator('#notifications-panel')).toBeVisible();
    await expect(page.locator('.notification-item').first()).toContainText('Welcome to Notifications Center');
  });

  test('disabled user does not see Notifications Center', async ({ page }) => {
    await seedUser(disabledUser);
    await page.goto('/login');
    await page.fill('[name=email]', disabledUser.email);
    await page.fill('[name=password]', 'password123');
    await page.click('[type=submit]');

    await expect(page.locator('#notifications-panel')).not.toBeVisible();
  });

  test('flag toggle persists across reload', async ({ page }) => {
    await seedUser(enabledUser);
    await page.goto('/dashboard');
    await expect(page.locator('#notifications-panel')).toBeVisible();

    await mockFlagService.setFlag(enabledUser.id, 'notificationsCenter', false);
    await page.reload();

    await expect(page.locator('#notifications-panel')).not.toBeVisible();
  });

  test('analytics events emitted correctly', async ({ page }) => {
    const analyticsEvents = [];
    page.on('request', (req) => {
      if (req.url().includes('/analytics')) analyticsEvents.push(req.postData());
    });

    await seedUser(enabledUser);
    await page.goto('/dashboard');

    expect(analyticsEvents).toContainEqual(expect.objectContaining({ event: 'notifications_panel_opened' }));
  });
});
```

## Why This Is Asked

Tests critical authorization paths, data-loss prevention, and audit integrity in multi-tenant setups, plus resilience to flaky services and retention policies.

## Key Concepts

- RBAC and DLP enforcement across tenants
- Tamper-evident audit logs (sequencing, signatures/HMAC)
- End-to-end data export redaction
- Seeds and mocks for deterministic, isolated tests
- Flaky service handling and time-based retention checks

## Code Example

```javascript
// Pseudo end-to-end test sketch (Playwright/Cypress-agnostic)
async function testRBACAndDLP() {
  const t = seedTenant('tenantA');
  const uOwner = seedUser(t, 'owner');
  const uEditor = seedUser(t, 'editor');
  const uAuditor = seedUser(t, 'auditor');
  const admin = seedUser(t, 'admin');

  // Owner creates a share with PII
  await login(uOwner);
  await createShare({ tenant: t.id, data: 'PII' });

  // Editor attempts restricted action
  await login(uEditor);
  assertAccessDenied(editShare(t.id));

  // Auditor reads audit trail
  await login(uAuditor);
  assertAuditIncludes(t.id, 'READ', uAuditor.id);

  // Admin exports with redaction
  await login(admin);
  const exportPayload = await exportData(t.id);
  assertRedacts(exportPayload, ['PII']);
  // Verify tamper-evident log
  assertTamperEvidence(t.id);
}
```

